import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.BZO4qERu.js";const C=JSON.parse('{"title":"OpenCode","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/opencode.md","filePath":"integrations/opencode.md","lastUpdated":1781331939000}'),i={name:"integrations/opencode.md"};function n(l,e,p,d,c,h){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="opencode" tabindex="-1">OpenCode <a class="header-anchor" href="#opencode" aria-label="Permalink to &quot;OpenCode&quot;">​</a></h1><p>OpenCode 可以通过 <a href="https://ccswitch.io/zh/docs?section=getting-started" target="_blank" rel="noreferrer">CC Switch</a> 配置 Tokeness。CC Switch 支持 OpenCode，并提供 OpenAI Compatible 预设。</p><h2 id="_1-准备-tokeness" tabindex="-1">1. 准备 Tokeness <a class="header-anchor" href="#_1-准备-tokeness" aria-label="Permalink to &quot;1. 准备 Tokeness&quot;">​</a></h2><p>先在 Tokeness 控制台完成：</p><ol><li>充值余额。</li><li>创建 OpenCode 专用 API Key。</li><li>在模型广场复制要使用的模型名。</li></ol><p>接口地址：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://n.tokeness.io/v1</span></span></code></pre></div><p>如果你还没确认 OpenCode 本体能正常运行，先把 OpenCode 装好，再回来填 Tokeness 配置。</p><h2 id="_2-在-cc-switch-添加供应商" tabindex="-1">2. 在 CC Switch 添加供应商 <a class="header-anchor" href="#_2-在-cc-switch-添加供应商" aria-label="Permalink to &quot;2. 在 CC Switch 添加供应商&quot;">​</a></h2><ol><li>打开 CC Switch。</li><li>左侧切换到 OpenCode。</li><li>点击右上角 <code>+</code>。</li><li>预设选择 OpenAI Compatible；如果没有该预设，选择“自定义”。</li><li>名称填写 <code>Tokeness</code>。</li><li>API Key 填写 Tokeness API Key。</li><li>Base URL 填写 <code>https://n.tokeness.io/v1</code>。</li><li>模型填写 Tokeness 模型广场中的模型名。</li><li>保存。</li></ol><p>CC Switch 支持从 OpenAI 兼容的 <code>/v1/models</code> 端点获取模型列表。若自动获取失败，手动填写模型名。</p><h2 id="_3-切换并重启终端" tabindex="-1">3. 切换并重启终端 <a class="header-anchor" href="#_3-切换并重启终端" aria-label="Permalink to &quot;3. 切换并重启终端&quot;">​</a></h2><p>在供应商卡片上点击“启用”。如果切换后没有立即生效，关闭当前终端并重新打开一次。</p><h2 id="_4-验证" tabindex="-1">4. 验证 <a class="header-anchor" href="#_4-验证" aria-label="Permalink to &quot;4. 验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opencode</span></span></code></pre></div><p>启动后输入：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你好，请简单介绍一下自己</span></span></code></pre></div><p>如果能正常回复，说明 OpenCode 已通过 CC Switch 使用 Tokeness。调用记录可在 Tokeness “使用日志”中查看。</p>',18)])])}const k=a(i,[["render",n]]);export{C as __pageData,k as default};
